import{_ as s,h as i,i as e,c as o,v as r,p as E,x as l,m as n,e as A,S as p}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"专家 vs 众包标注","description":"","frontmatter":{"title":"专家 vs 众包标注","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-vs-crowd.md","filePath":"llm/expert-vs-crowd.md","lastUpdated":1788454257000}'),d={name:"llm/expert-vs-crowd.md"};function h(c,a,m,B,u,_){const t=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="专家-vs-众包标注" tabindex="-1">专家 vs 众包标注 <a class="header-anchor" href="#专家-vs-众包标注" aria-label="Permalink to &quot;专家 vs 众包标注&quot;">​</a></h1><div class="epigraph"><p>谁来比「哪一条更好」，决定奖励模型学的是哪一种人类。众包便宜、覆盖日常有用；专家贵、覆盖政策与专业真值。混用而不写清协议，等于把两种噪声当成一种信号。</p><footer>—— 对照 Askell 等把 HHH 写成实验室指南、Bai 等 HH-RLHF 用分头偏好与红队收集无害比较，以及 InstructGPT / Llama 2 对标注员培训与抽检的工程实践</footer></div><p>偏好数据不是中性的成对比特。标注员池、培训、时薪与抽检规则，都会进 <a href="/llm/bradley-terry">Bradley-Terry</a> 拟合的 \\(r(x,y)\\)。InstructGPT 用承包标注员按书面指南写示范、做比较；Llama 2 把有用性与安全性拆开采集，安全侧更依赖受训的红队与政策熟悉度。Askell 的 HHH 实验室把轴写清楚，但没有声称众包能同时当三轴的金标准。Bai 的 HH-RLHF 则表明：无害比较若仍按「谁答得全」来选，会与有用比较同源。本篇写专家与众包各自能标什么、协议如何分层、以及评测时如何避免「换一批评注员，模型就换人格」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>众包的优势是规模与日常语感：开放写作、格式、是否听懂口语请求，众包与产品用户更近。劣势是政策分辨率低。无害类别的边界（合法安全研究 vs 可执行危害、新闻暴力 vs 煽动）、专业诚实（医学剂量、法律程序、论文是否存在），众包没有标准答案键时会靠文风投票。专家的优势是类别内一致性与真值；劣势是贵、慢、风格偏学术或偏审查员，有用轴上可能惩罚口语短答、奖励冗长免责。</p><p>把所有比较丢给同一市场，看起来「人类反馈」统一了，其实是把最贵的轴用最便宜的协议来标。反过来，把日常「总结这封邮件」也交给领域律师，会把有用头训成法律备忘录腔。问题是分层，不是「专家一定更对齐」。</p><h3 id="一致率高不等于轴标对了" tabindex="-1">一致率高不等于轴标对了 <a class="header-anchor" href="#一致率高不等于轴标对了" aria-label="Permalink to &quot;一致率高不等于轴标对了&quot;">​</a></h3><p>众包内部一致率可以很高：大家都喜欢列表、emoji、先道歉再答。这是风格共识，不是 <a href="/llm/hhh-axes">HHH</a> 三轴都校准了。专家内部也会分歧，尤其无害边界与「应不应该给替代方案」。报告协议时应分开写：众包有用对的一致率、专家无害对的一致率、专家–众包交叉一致率。交叉低时，不能把两套标签平均成一条 \\(y_w\\)，否则 RM 拟合的是互相对抗的监督。</p><p><span class="marginnote">红队专家生产的是对抗性 \\(x\\)，不是自动更高质量的 \\(y\\)。无害比较的赢方仍要按政策写：拒、改写、给合法替代。只有 \\(x\\) 很难、\\(y\\) 仍是众包随手写的拒答模板，专家劳动被浪费在题面上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按轴选池。有用比较：众包或产品用户抽样，指南强调完成意图、澄清、不要为长度加分。无害比较：受训标注员或安全专家，先考政策再上岗，抽检由第二专家复审；题面可来自红队。诚实比较：需要答案键或检索证据，标「是否虚构、是否承认无知」，宜用具备领域知识的专家或工具辅助的流程，而不是纯文风比较。Bai 等人把有用与无害分头，正是承认同一批人很难同时当两套金标准。</p><p>培训不是发一页 PDF。有效做法是：金标标定集（专家先标一小套）、上岗考试、定期校准会、对困难项的申诉通道。众包侧用更短的指南加反例（「短而正确应赢过长而空」）。专家侧用类别清单与允许的反例，避免只记禁止词。时薪过低时，众包会加速点击，成对噪声上升，看起来像需要更大 RM，其实是标签熵。</p>',12)),(e(),E(p,null,{default:l(()=>[A(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AXIS%5B%22%E6%8C%89%E8%BD%B4%E5%88%86%E6%B5%81%22%5D%20--%3E%20HELP%5B%22%E6%9C%89%E7%94%A8%EF%BC%9A%E4%BC%97%E5%8C%85%20%2B%20%E7%9F%AD%E6%8C%87%E5%8D%97%22%5D%0A%20%20AXIS%20--%3E%20HARM%5B%22%E6%97%A0%E5%AE%B3%EF%BC%9A%E5%8F%97%E8%AE%AD%E5%91%98%20%2F%20%E4%B8%93%E5%AE%B6%20%2B%20%E6%94%BF%E7%AD%96%E8%80%83%E8%AF%95%22%5D%0A%20%20AXIS%20--%3E%20HON%5B%22%E8%AF%9A%E5%AE%9E%EF%BC%9A%E7%AD%94%E6%A1%88%E9%94%AE%E6%88%96%E6%A3%80%E7%B4%A2%E8%BE%85%E5%8A%A9%22%5D%0A%20%20HELP%20--%3E%20QA1%5B%22%E9%87%91%E6%A0%87%E6%8A%BD%E6%A3%80%22%5D%0A%20%20HARM%20--%3E%20QA2%5B%22%E4%B8%93%E5%AE%B6%E5%A4%8D%E5%AE%A1%22%5D%0A%20%20HON%20--%3E%20QA3%5B%22%E5%B7%A5%E5%85%B7%E5%A4%8D%E6%A0%B8%E5%87%BA%E5%A4%84%22%5D%0A%20%20QA1%20--%3E%20RM%5B%22%E5%88%86%E5%A4%B4%E5%A5%96%E5%8A%B1%E6%88%96%E5%88%86%E5%A4%B4%E6%AF%94%E8%BE%83%22%5D%0A%20%20QA2%20--%3E%20RM%0A%20%20QA3%20--%3E%20RM%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>成本上不要用「专家比例」一个数交差。应报：每轴的条数、每对的复标数、专家小时、众包小时、抽检通过率。HH-RLHF 类流程里，无害数据往往更贵、更少，RM 更容易过拟合拒答句式；有用数据更多，更容易过拟合长度。配额要按轴的失败代价定，不能按市场单价倒推。</p><h3 id="金标、抽检与漂移" tabindex="-1">金标、抽检与漂移 <a class="header-anchor" href="#金标、抽检与漂移" aria-label="Permalink to &quot;金标、抽检与漂移&quot;">​</a></h3><p>专家金标集用于：(1) 众包上岗；(2) 持续抽检；(3) 持有评测。金标要定期重标一部分，因为政策会改、标注员会疲。漂移表现为：同一对在三个月后胜者翻转率升高，或专家–众包交叉一致率下滑。发现漂移应停增数据、开校准，而不是继续灌进 RM 再靠早停。InstructGPT 类流水线把指南版本与数据版本绑在一起，换指南等于换数据集。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BT 似然把标注员当成无偏的 logistic 噪声。池不匹配时，噪声是结构化的：众包在无害题上系统偏好「看起来在帮忙」，专家系统偏好「先挡」。\\(r\\) 会学到一个随 \\(x\\) 的题型而切换的幽灵标注员。策略沿 \\(r\\) 优化后，日常题更像众包人格，敏感词附近突然切换到专家拒答腔——用户感觉到的「人格分裂」往往是池的拼接，不是解码温度。</p><p>专家少、众包多时，梯度以众包为主，专家标签变成正则。若把两套数据简单 concat，要按轴加权或分头，否则无害专家信号会被有用众包淹没。分头之后，组合权重 \\(\\lambda\\) 成为显式的「听谁的」旋钮，比把人藏进一个池更可审计。</p><p><span class="marginnote">领域专家不是单一物种。生物安全、网络滥用、儿童安全的专家指南不同，不能共用一个「安全专家」队列而不分队列。分队列等于再一次分头。</span></p><h3 id="何时必须专家-何时众包足够" tabindex="-1">何时必须专家，何时众包足够 <a class="header-anchor" href="#何时必须专家-何时众包足够" aria-label="Permalink to &quot;何时必须专家，何时众包足够&quot;">​</a></h3><p>必须专家或等价工具：需要真值或法规边界的比较、无害政策的边界题、医疗法律财务的「能不能答」。众包足够：文风、结构、是否遵循多约束指令、是否漏了用户列明的格式。模糊区（表面敏感的科普）需要带允许反例的受训员，纯众包会过拒绝，纯审查专家会过拒绝得更厉害，要用 <a href="/llm/over-refusal">过拒绝</a> 探针约束。AI 反馈可以减轻专家看有害全文的量，见 <a href="/llm/aif-as-preference">AI 反馈</a>，但不能用教师模型的众包人格去冒充专家政策。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>专家也会有机构偏见：更怕漏报，于是无害轴整体右移，产品过拒绝。要用无害敏感但应回答的对照集做回归，而不是只听专家的一致率。众包会有文化与语言偏置：英语母语标注员对其他语言的「有用」判断不可靠，应按语言分层建池。</p><p>不要把产品用户的隐式点击直接当众包金标，见 <a href="/llm/implicit-feedback-prefs">隐式反馈</a>。点击有位置偏置，且用户会奖励谄媚。专家与众包都是显式协议；隐式是另一套生成过程。三者可以做特征，不能偷偷平均成一对 \\((y_w,y_l)\\)。</p><p><span class="marginnote">公开 HH 比较集的标注员构成与你的承包商不同。用 HH 预训练偏好头，再用自己的专家无害对做适应，要报告两段数据的轴覆盖，避免以为「已经用过人类反馈」即覆盖本产品政策。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>众包适合有用轴的规模与日常语感；专家适合无害边界与带真值的诚实。</li><li>一致率要分轴、分池报告；交叉一致率低时不要平均成一条总序。</li><li>按轴分流、金标考试、抽检与指南版本化，是协议，不是可选管理。</li><li>数据量不平衡时必须分头或加权，否则专家信号被众包梯度盖掉。</li><li>专家偏漏报会推高过拒绝；众包偏文风会推高长度与谄媚。</li><li>出处：Askell et al., 2021（HHH 坐标系）；Bai et al., HH-RLHF, 2022（分头偏好与红队）；Ouyang 等 InstructGPT、Touvron 等 Llama 2 的标注工程。</li></ul>',15))])}const x=s(d,[["render",h]]);export{f as __pageData,x as default};
